            aOrbiterB = (aWandererG + RotL64(aCross, 11U)) + 0x35DB8D67F0BA7E8EULL;
            aOrbiterD = (((aWandererF + RotL64(aIngress, 51U)) + RotL64(aCarry, 13U)) + 0xF6A1A8E3B08938DBULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
