            aOrbiterH = ((aWandererH + RotL64(aCross, 29U)) + RotL64(aCarry, 21U)) + 0xDBEC0DC9137EFCAFULL;
            aOrbiterI = (((aWandererB + RotL64(aIngress, 44U)) + RotL64(aCarry, 3U)) + 0x36276AA3F54F85D1ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aPrevious, 5U)) + 0xFA9A5C8C88C62528ULL) + aTwistOrbiterAssignSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aIngress, 37U)) + 0xBA27ED4E04FE3A2EULL;
            aOrbiterB = ((aWandererJ + RotL64(aScatter, 19U)) + RotL64(aCarry, 41U)) + 0xA798E16AE9B9267EULL;
            aOrbiterJ = (aWandererK + RotL64(aCross, 13U)) + 0x51FB0D105515CE7FULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x4F6F1B97C3C429C3ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x2831EC57E0422A25ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x8E9A2BF5E559C97BULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xF8F258F593665BB6ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x7D35255359BCA6D1ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 15U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x4219665E43C333E1ULL), 35U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0xED65564D2643EAEFULL) + aTwistOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0xFC5498E96B8D56AEULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xF4F5C905F61D6093ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xDD3B181E61717BA9ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x7ADC2D3EAFD4356CULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 16U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x8DD1E4A2AA7E47D1ULL), 27U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xBC0F7B64FEF0520FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0xA20CBBB508603CD4ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x91414615CC28293FULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x94BC95D8E8BB8477ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0xBA91FC6DD24365CFULL;
            aOrbiterB = RotL64((aOrbiterB * 0xCEEB484A93A5E913ULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x481AEF2AB0695045ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x65C73160379ED728ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE98CF21979D40BD3ULL), 21U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterD, 21U);
