            aWandererG = aWandererG + ((RotL64(aPrevious, 5U) + aOrbiterB) + RotL64(aOrbiterJ, 44U));
            aWandererH = aWandererH ^ ((RotL64(aIngress, 23U) + aOrbiterH) + RotL64(aOrbiterJ, 57U));
