            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x5F306CAC406A6D3EULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x191AA1C61FAF4A4BULL;
