            aOrbiterE = RotL64((aOrbiterE * 0x1DB04F96F5EF4681ULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xB32D9D424E741C27ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0x3BBAF0F71F2B774CULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 25U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xEE4FB9DCC7F7C66DULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x65413E1BA1672B50ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x63B1E69DF883F6EAULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x81C52796A2CC2779ULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xB4BD515AAFEEA276ULL;
