            aIngress = (RotL64(aPoisonLaneA[((aIndex + 2194U)) & S_BLOCK1], 3U) ^ RotL64(aPoisonLaneB[((aIndex + 7847U)) & S_BLOCK1], 26U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 1066U)) & W_KEY1], 39U) ^ RotL64(aWoodLaneB[((aIndex + 1488U)) & S_BLOCK1], 13U));
