            aOrbiterD = (aWandererA + RotL64(aPrevious, 21U)) + 0xF172C691C76DEE14ULL;
            aOrbiterK = ((aWandererF + RotL64(aScatter, 60U)) + RotL64(aCarry, 21U)) + 0x745FAD89786ED8AEULL;
            aOrbiterB = (aWandererG + RotL64(aCross, 47U)) + 0x878E7E4536B62E34ULL;
            aOrbiterF = (aWandererB + RotL64(aIngress, 37U)) + 0xBA42767F3B27A95FULL;
            aOrbiterJ = (((aWandererK + RotL64(aCross, 53U)) + RotL64(aCarry, 3U)) + 0xA2913D0734E8E317ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterG = (((aWandererJ + RotL64(aIngress, 27U)) + RotL64(aCarry, 37U)) + 0x4C9586F3F2B9582CULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 18U)) & S_SALT1];
