            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xF0357C332A771254ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1A886554AE662611ULL), 53U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x7514CF1B14922F09ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x85FCC397E3845D74ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xCA5D796FA3253975ULL), 21U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0x912563C84D8BBF78ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0xA3C335A5D6CB5F7CULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6E03625447C9F8F3ULL), 5U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterB, 47U);
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterF, 13U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterC, 41U));
