            //
            aWandererI = aWandererI ^ (((RotL64(aScatter, 29U) + RotL64(aOrbiterK, 57U)) + aOrbiterF) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 21U)) & S_SALT1]);
