            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 12674U)) & S_BLOCK1], 21U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 15368U)) & S_BLOCK1], 40U));
            aCross ^= (RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 13414U)) & S_BLOCK1], 3U) ^ RotL64(aLightningLaneD[((aIndex + 15742U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCross, 54U) ^ RotL64(aIngress, 27U)) ^ (RotL64(aPrevious, 39U) + RotL64(aCarry, 13U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterF = ((aWandererB + RotL64(aScatter, 19U)) + RotL64(aCarry, 5U)) + 0x29D3672EE4063C7AULL;
            aOrbiterD = ((aWandererE + RotL64(aIngress, 58U)) + 0x30CD1081D1AE48C9ULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 11U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aPrevious, 5U)) + 0x0BF815BF0169F43EULL;
            aOrbiterA = (aWandererC + RotL64(aCross, 41U)) + 0x2663B08FDBDD04E9ULL;
            aOrbiterG = (((aWandererA + RotL64(aIngress, 11U)) + RotL64(aCarry, 41U)) + 0xCCD8547A112A8442ULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 12U)) & S_SALT1];
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 29U)) + RotL64(aCarry, 29U)) + 0xACD3C73363415FADULL;
            aOrbiterJ = (aWandererH + RotL64(aScatter, 35U)) + 0x67E69080BD6416DFULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x679C98992389E4BEULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0xB9E762629ADF2BCCULL;
            aOrbiterB = RotL64((aOrbiterB * 0x6DD90D2287E9E1E5ULL), 21U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x8EDC710D6D51CAACULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xA67912B5338E1DE5ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x0692DAF03C16259FULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0xC1A7855B7751E381ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x6DF2F2DF4925D67BULL;
            aOrbiterA = RotL64((aOrbiterA * 0x105D29AC52CBB48DULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x65999D3904F1A155ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0xD72DC676204AE8E4ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCF078F2FCD913B4FULL), 5U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0xEDE17D68CF44CAEBULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x3082B24B3AFBC8F2ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 24U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x588D07F54A551E7FULL), 13U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x5236AEAD220E6B3BULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x5DF93429C17F3524ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x12984CEE34EAC661ULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x432D016D811EC54EULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0xF50285E764B27D25ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x51D640A09570484BULL), 41U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterA, 53U);
            aIngress = aIngress + (RotL64(aOrbiterJ, 37U) ^ aOrbiterD);
            aIngress = aIngress + (RotL64(aOrbiterF, 13U) ^ aOrbiterK);
            aIngress = aIngress + RotL64(aOrbiterB, 29U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererG = aWandererG + (((RotL64(aScatter, 11U) + RotL64(aOrbiterF, 13U)) + aOrbiterD) + RotL64(aCarry, 5U));
            aWandererB = aWandererB ^ (((RotL64(aPrevious, 35U) + RotL64(aOrbiterF, 29U)) + aOrbiterK) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aCross, 22U) + aOrbiterG) + RotL64(aOrbiterD, 51U)) + aKeyRotateWandererUpdateSaltC[((aIndex + 15U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 29U) + RotL64(aOrbiterG, 57U)) + aOrbiterJ);
