    std::uint64_t *aKeyRotateOrbiterUpdateSaltB = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterUpdate.mSaltB;
    std::uint64_t *aKeyRotateOrbiterUpdateSaltC = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterUpdate.mSaltC;
    std::uint64_t *aKeyRotateOrbiterUpdateSaltD = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterUpdate.mSaltD;
    std::uint64_t *aKeyRotateOrbiterUpdateSaltE = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterUpdate.mSaltE;
    std::uint64_t *aKeyRotateOrbiterUpdateSaltF = pWorkSpace->mDomainBundle.mKeyRotateSalts.mOrbiterUpdate.mSaltF;
    std::uint64_t *aKeyRotateWandererUpdateSaltA = pWorkSpace->mDomainBundle.mKeyRotateSalts.mWandererUpdate.mSaltA;
    std::uint64_t *aKeyRotateWandererUpdateSaltB = pWorkSpace->mDomainBundle.mKeyRotateSalts.mWandererUpdate.mSaltB;
    std::uint64_t *aKeyRotateWandererUpdateSaltC = pWorkSpace->mDomainBundle.mKeyRotateSalts.mWandererUpdate.mSaltC;
    std::uint64_t *aKeyRotateWandererUpdateSaltD = pWorkSpace->mDomainBundle.mKeyRotateSalts.mWandererUpdate.mSaltD;
    std::uint64_t *aKeyRotateWandererUpdateSaltE = pWorkSpace->mDomainBundle.mKeyRotateSalts.mWandererUpdate.mSaltE;
    std::uint64_t *aKeyRotateWandererUpdateSaltF = pWorkSpace->mDomainBundle.mKeyRotateSalts.mWandererUpdate.mSaltF;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [grow arx]
    std::uint64_t aPrevious = *pPrevious;
    std::uint64_t aIngress = *pIngress;
    std::uint64_t aCarry = *pCarry;
    std::uint64_t aWandererA = *pWandererA;
    std::uint64_t aWandererB = *pWandererB;
    std::uint64_t aWandererC = *pWandererC;
    std::uint64_t aWandererD = *pWandererD;
    std::uint64_t aWandererE = *pWandererE;
