            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 1415U)) & S_BLOCK1], 3U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 1359U)) & W_KEY1], 56U));
            aCross ^= (RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 4439U)) & S_BLOCK1], 13U) ^ RotL64(aKeyRowReadA[(((2047U - aIndex) + 2898U)) & W_KEY1], 39U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCross, 54U) + RotL64(aIngress, 41U)) ^ (RotL64(aPrevious, 19U) ^ RotL64(aCarry, 5U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterB = ((aWandererC + RotL64(aScatter, 57U)) + 0xC889CDA4ADF0B6FAULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 14U)) & S_SALT1];
            aOrbiterH = (((aWandererB + RotL64(aPrevious, 39U)) + RotL64(aCarry, 3U)) + 0x341DE8F06460252EULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterD = (aWandererK + RotL64(aIngress, 50U)) + 0xB82B5A548B596D24ULL;
            aOrbiterE = ((aWandererD + RotL64(aCross, 19U)) + RotL64(aCarry, 13U)) + 0x2477774DA7139AC5ULL;
            aOrbiterK = (aWandererA + RotL64(aIngress, 37U)) + 0x79FA0863C5287A15ULL;
            aOrbiterA = (aWandererG + RotL64(aPrevious, 47U)) + 0x915298F13A7F6F76ULL;
            aOrbiterI = (aWandererI + RotL64(aCross, 23U)) + 0x67A02A82CCA43345ULL;
            aOrbiterC = (aWandererF + RotL64(aScatter, 3U)) + 0x13428855E522AC70ULL;
            aOrbiterG = (aWandererH + RotL64(aIngress, 52U)) + 0xB098A15CF038AB64ULL;
            aOrbiterF = ((aWandererE + RotL64(aScatter, 43U)) + RotL64(aCarry, 27U)) + 0x30C35F9BA74351B4ULL;
            aOrbiterJ = (aWandererJ + RotL64(aPrevious, 11U)) + 0xDBAC9CBF89ED6CC5ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x838B77671BBCCBD7ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xACB3BD2AE6E51B02ULL;
