            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0xCCA17A4C1928E8E3ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xDE6A0724335B8093ULL), 3U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x08C90EDAD573C208ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x24A945658A4F07C8ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x7BF90C9ABE213A0DULL), 23U);
            //
