            aIngress = aIngress + RotL64(aOrbiterJ, 51U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ ((RotL64(aScatter, 47U) + RotL64(aOrbiterJ, 41U)) + aOrbiterB);
            aWandererJ = aWandererJ + ((RotL64(aPrevious, 44U) + aOrbiterI) + RotL64(aOrbiterA, 11U));
            aWandererD = aWandererD ^ ((RotL64(aCross, 29U) + aOrbiterC) + RotL64(aOrbiterJ, 22U));
