            aWandererC = aWandererC + ((RotL64(aPrevious, 57U) + RotL64(aOrbiterI, 51U)) + aOrbiterK);
            aWandererI = aWandererI ^ (((RotL64(aCross, 39U) + RotL64(aOrbiterH, 43U)) + aOrbiterD) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aIngress, 3U) + RotL64(aOrbiterK, 53U)) + aOrbiterH);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 19U) + aOrbiterC) + RotL64(aOrbiterE, 60U));
            aWandererH = aWandererH + (((RotL64(aCross, 11U) + RotL64(aOrbiterB, 37U)) + aOrbiterC) + RotL64(aCarry, 53U));
            aWandererE = aWandererE ^ (((RotL64(aScatter, 34U) + aOrbiterD) + RotL64(aOrbiterA, 19U)) + aKeyRotateWandererUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererG, 47U));
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererI, 52U));
