            //
            aOrbiterA = ((aWandererG + RotL64(aScatter, 37U)) + RotL64(aCarry, 47U)) + 0x10DB078D98943D82ULL;
            aOrbiterJ = ((aWandererH + RotL64(aIngress, 22U)) + 0x70D4AA53DC78C3AAULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 27U)) & S_SALT1];
            aOrbiterC = (((aWandererC + RotL64(aCross, 35U)) + RotL64(aCarry, 53U)) + 0xE1B5A8F7370E213DULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 4U)) & S_SALT1];
            aOrbiterK = ((aWandererK + RotL64(aPrevious, 3U)) + RotL64(aCarry, 19U)) + 0x998B609D1A61EE69ULL;
            aOrbiterG = (aWandererB + RotL64(aScatter, 57U)) + 0xE8CCF67A7CBDC668ULL;
            aOrbiterH = (aWandererJ + RotL64(aCross, 41U)) + 0x7E231943414FC18AULL;
