            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x0F11133F73AF64A1ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x6637A151BAAAA96BULL;
            aOrbiterC = RotL64((aOrbiterC * 0x5E9BF13DEE20F665ULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x2AB622AE6544563FULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x266E5186F6E6D1ECULL;
            aOrbiterH = RotL64((aOrbiterH * 0x3E2C2A055ABA798DULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x98F47088FBB67B2EULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x66511AF25D398840ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xAB7ED49145697741ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x964C24844040BC2AULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x27F0A1A929D94DC3ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xBC468091EE4EF5E5ULL), 23U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x2A7084AA0F642649ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0xB80C4EBCAC5204F4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2CCE126D8CF26ECBULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x6B0B8B33DE2B17D6ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0x10A669E42E66E8DAULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x06CA484134A4C595ULL), 5U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x8A50FE047E680E0FULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xD67C250631EDDD22ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xB9830E1108E034EBULL), 53U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x6139FB114DB6A362ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xFAC088D8FCE68BF4ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4E908E4E25FD79D7ULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x7598D72A3B652309ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0xE88A7559846ACBB3ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x4BA9C33D15CEDA87ULL), 21U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x09D3C9AFB1BE2A41ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterH) ^ 0x47EB022D48919CA1ULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xAC7D5EEE3654E05BULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x05FC1E9A9A43CF4AULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x901AFBDEB9011B59ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEE1E999A02D19B21ULL), 57U);
