            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0xB5E68A51530CC445ULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0xE5A99861359264B6ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
