            aIngress = (RotL64(aKineticLaneA[((aIndex + 10070U)) & S_BLOCK1], 23U) ^ RotL64(aAetherLaneC[((aIndex + 9328U)) & S_BLOCK1], 34U));
            aIngress ^= (RotL64(aPlasmaLaneD[((aIndex + 7952U)) & S_BLOCK1], 3U) ^ RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 9057U)) & S_BLOCK1], 13U));
            aIngress = TwistMix64::DiffuseA(aIngress);
