            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 5899U)) & S_BLOCK1], 37U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 5896U)) & S_BLOCK1], 19U));
            aCross ^= (RotL64(aVaporLaneD[((S_BLOCK1 - aIndex + 5902U)) & S_BLOCK1], 28U) ^ RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 8670U)) & S_BLOCK1], 47U));
