            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x4534D16B7B05E8A3ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0x562A9B5313AAFBA7ULL) ^ aKeySpawnOrbiterUpdateSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xBBD8E7BE6152AB81ULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x14FC1C2590148F59ULL;
