            aWandererG = aWandererG ^ (((RotL64(aPrevious, 20U) + aOrbiterG) + RotL64(aOrbiterF, 21U)) + aKeySpawnWandererUpdateSaltB[((aIndex + 21U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aIngress, 57U) + RotL64(aOrbiterG, 13U)) + aOrbiterH);
            aWandererI = aWandererI ^ ((RotL64(aScatter, 3U) + aOrbiterH) + RotL64(aOrbiterK, 5U));
