            aWandererK = aWandererK ^ (((RotL64(aScatter, 11U) + aOrbiterJ) + RotL64(aOrbiterG, 46U)) + aKeySpawnWandererUpdateSaltA[((aIndex + 19U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aPrevious, 29U) + RotL64(aOrbiterI, 35U)) + aOrbiterJ);
