            aOrbiterF = (aWandererI + RotL64(aIngress, 29U)) + 0x446BC7628FA3EBE9ULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0xCCC8150131303E4FULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xBB56883414E5C436ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x4B31E4C3C4B78A39ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x931B285BCD78D325ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x2F4B8B31E15224C1ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xC901F70B93F42C6DULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xBDDB6B7225E58BECULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0xC994A44C8A13B9ACULL) ^ aKeySpawnOrbiterUpdateSaltE[((aIndex + 20U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xB3B283F8F5A233C7ULL), 51U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0xB6C85E5D52B1FB09ULL) + aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0x77E1E6BB0C23D9D3ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x2D1D32329A927B7BULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x46A2723E680AB7A3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xE920C390B717139CULL;
