            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x6AB5979B85F98B37ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x975EBE4F4122F6F8ULL) ^ aKeySpawnOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
